def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

solutions = []
# Check x from 4 up to 30 to find solutions
for x in range(4, 31):
    target = x**3 + x - 2
    if is_power_of_two(target):
        # target = 2^k, so k = log2(target)
        k = target.bit_length() - 1
        solutions.append((x, k))

print("Found solutions (x, k):")
for sol in solutions:
    print(sol)
